const { sendWelcome } = require('./welcome');

describe('sendWelcome', () => {
  let repo;
  let mailer;

  beforeEach(() => {
    repo = { findById: jest.fn() };
    mailer = { send: jest.fn().mockResolvedValue(undefined) };
  });

  test('ส่งอีเมลต้อนรับและคืน sent true เมื่อผู้ใช้มีอีเมล', async () => {
    repo.findById.mockResolvedValue({ id: 1, email: 'a@example.com' });

    const result = await sendWelcome({ repo, mailer }, 1);

    expect(result).toEqual({ sent: true });
    expect(mailer.send).toHaveBeenCalledWith(
      expect.objectContaining({ to: 'a@example.com' })
    );
  });

  test('ไม่ส่งอีเมลและคืน sent false เมื่อผู้ใช้ไม่มีอีเมล', async () => {
    repo.findById.mockResolvedValue({ id: 2, email: null });

    const result = await sendWelcome({ repo, mailer }, 2);

    expect(result).toEqual({ sent: false });
    expect(mailer.send).not.toHaveBeenCalled();
  });

  test('throw user not found เมื่อไม่พบผู้ใช้ และไม่ส่งอีเมล', async () => {
    repo.findById.mockResolvedValue(null);

    await expect(sendWelcome({ repo, mailer }, 3)).rejects.toThrow('user not found');
    expect(mailer.send).not.toHaveBeenCalled();
  });
});

